void loop() { 
  // -------------------------------------------------------------------------- 
  // 1. Non-Blocking Execution Guard 
  // -------------------------------------------------------------------------- 
  if (millis() - lastUpdate < updateInterval) { 
    return; // Yield control immediately; preserve CPU responsiveness 
  } 
  lastUpdate = millis(); // Refresh operational execution timestamp 

